  ('e93b942f-dba7-4a50-ae37-68763bc9bbda', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$lHkh fØ;k,¡ bruh xfjekiw.kZ <ax ls dha fd mldh gj Hkafxek ls yxrk Fkk ekuks t;t;oarh osQ lqj xw¡t jgs gksaA ogk¡ dk okrkoj.k bruk 'kkar Fkk fd pk;nkuh osQ ikuh dk [kncnkuk Hkh lqukbZ ns jgk FkkA$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('579a1568-17e3-45b4-b807-94bb4e812d7b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चाय तैयार हुई। उसने वह प्यालों में भरी। फिर वे प्याले हमारे सामने रख दिए गए। वहाँ हम तीन मित्र ही थे। इस विधि में शांति मुख्य बात होती है। इसलिए वहाँ तीन से अधिक आदमियों को प्रवेश नहीं दिया जाता। प्याले में दो घूँट से अधिक चाय नहीं थी। हम ओठों से प्याला लगाकर एक-एक बूँद चाय पीते रहे। करीब डेढ़ घंटे तक चुस्कियों का यह सिलसिला चलता रहा। पहले दस-पंद्रह मिनट तो मैं उलझन में पड़ा। फिर देखा, दिमाग की रफ़्तार धीरे-धीरे धीमी पड़ती जा रही है। थोड़ी देर में बिल्कुल बंद भी हो गई। मुझे लगा, मानो अनंतकाल में मैं जी रहा हूँ। यहाँ तक कि सन्नाटा भी मुझे सुनाई देने लगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('72e1598d-1cbd-447f-aa34-b0d6f8827009', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अक्सर हम या तो गुज़रे हुए दिनों की खट्टी-मीठी यादों में उलझे रहते हैं या भविष्य के रंगीन सपने देखते रहते हैं। हम या तो भूतकाल में रहते हैं या भविष्यकाल में। असल में दोनों काल मिथ्या हैं। एक चला गया है, दूसरा आया नहीं है। हमारे सामने जो वर्तमान क्षण है, वही सत्य है। उसी में जीना चाहिए। चाय पीते-पीते उस दिन मेरे दिमाग से भूत और भविष्य दोनों काल उड़ गए थे। केवल वर्तमान क्षण सामने था। और वह अनंतकाल जितना विस्तृत था। जीना किसे कहते हैं, उस दिन मालूम हुआ। ज़ेन परंपरा की यह बड़ी देन मिली है जापानियों को!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('64759033-b08c-4af6-b86d-7ebc534b59e7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चाय तैयार हुई। उसने वह प्यालों में भरी। फिर वे प्याले हमारे सामने रख दिए गए। वहाँ हम तीन मित्र ही थे। इस विधि में शांति मुख्य बात होती है। इसलिए वहाँ तीन से अधिक आदमियों को प्रवेश नहीं दिया जाता। प्याले में दो घूँट से अधिक चाय नहीं थी। हम ओठों से प्याला लगाकर एक-एक बूँद चाय पीते रहे। करीब डेढ़ घंटे तक चुस्कियों का यह सिलसिला चलता रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a4ae42ae-12d4-4e91-8554-5d006d0deb32', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पहले दस-पंद्रह मिनट तो मैं उलझन में पड़ा। फिर देखा, दिमाग की रफ़्तार धीरे-धीरे धीमी पड़ती जा रही है। थोड़ी देर में बिल्कुल बंद भी हो गई। मुझे लगा, मानो अनंतकाल में मैं जी रहा हूँ। यहाँ तक कि सन्नाटा भी मुझे सुनाई देने लगा। अक्सर हम या तो गुज़रे हुए दिनों की खट्टी-मीठी यादों में उलझे रहते हैं या भविष्य के रंगीन सपने देखते रहते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('660c0dd0-763e-4b46-9a18-6c46a36c0acf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम या तो भूतकाल में रहते हैं या भविष्यकाल में। असल में दोनों काल मिथ्या हैं। एक चला गया है, दूसरा आया नहीं है। हमारे सामने जो वर्तमान क्षण है, वही सत्य है। उसी में जीना चाहिए। चाय पीते-पीते उस दिन मेरे दिमाग से भूत और भविष्य दोनों काल उड़ गए थे। केवल वर्तमान क्षण सामने था। और वह अनंतकाल जितना विस्तृत था। जीना किसे कहते हैं, उस दिन मालूम हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c0a5c1f7-e245-4397-bcf4-a680ca78ba12', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ज़ेन परंपरा की यह बड़ी देन मिली है जापानियों को! चाय तैयार हुई। उसने वह प्यालों में भरी। फिर वे प्याले हमारे सामने रख दिए गए। वहाँ हम तीन मित्र ही थे। इस विधि में शांति मुख्य बात होती है। इसलिए वहाँ तीन से अधिक आदमियों को प्रवेश नहीं दिया जाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
