  ('47aa219f-9aa7-40ab-8a4b-c6e86be95555', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चाय तैयार हुई। उसने वह प्यालों में भरी। फिर वे प्याले हमारे सामने रख दिए गए। वहाँ हम तीन मित्र ही थे। इस विधि में शांति मुख्य बात होती है। इसलिए वहाँ तीन से अधिक आदमियों को प्रवेश नहीं दिया जाता। प्याले में दो घूँट से अधिक चाय नहीं थी। हम ओठों से प्याला लगाकर एक-एक बूँद चाय पीते रहे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c921171a-b5b5-4afe-9609-7bb2cf71386f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', '61bfb252-1fab-4818-842e-66593ff85b98', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$करीब डेढ़ घंटे तक चुस्कियों का यह सिलसिला चलता रहा। पहले दस-पंद्रह मिनट तो मैं उलझन में पड़ा। फिर देखा, दिमाग की रफ़्तार धीरे-धीरे धीमी पड़ती जा रही है। थोड़ी देर में बिल्कुल बंद भी हो गई। मुझे लगा, मानो अनंतकाल में मैं जी रहा हूँ। यहाँ तक कि सन्नाटा भी मुझे सुनाई देने लगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-43-388Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
